CH('gov','From citizen complaints to a service improvement memo','من شكاوى المواطنين لمذكرة تحسين خدمة',[
['Theme the complaints','صنّف الشكاوى',["Citizen services analyst in a public-sector entity","Group the quarter’s citizen complaints into themes by service","- Attached: complaints export (reference, service, channel, date, text) with personal data masked","Leadership needs to see where services fail most","- Each theme counted with 2 anonymised quotes\n- No complaint dropped; unclear ones in an Other group","Theme table by service."],["محلل خدمة مواطنين في جهة حكومية","جمّع شكاوى المواطنين بتاعة الربع في مواضيع حسب الخدمة","- مرفق: تصدير الشكاوى (الرقم المرجعي، الخدمة، القناة، التاريخ، النص) والبيانات الشخصية متخفية","القيادة محتاجة تشوف الخدمات بتقع فين أكتر","- كل موضوع بعدده وجملتين من غير هوية\n- مفيش شكوى تتشال؛ والمش واضحة في مجموعة «أخرى»","جدول المواضيع حسب الخدمة."]],
['Find root causes','دوّر على الأسباب الجذرية',["Process improvement specialist in a government entity","Map the top 3 themes to process steps and likely root causes","- Themes: "+O1+"\n- Service process maps and standards: [paste]","Fixes must target the cause, not the symptom","- Causes linked to a process step with evidence\n- Assumptions marked [TO VERIFY]","Cause table per theme."],["أخصائي تحسين عمليات في جهة حكومية","اربط أهم 3 مواضيع بخطوات العملية والأسباب المحتملة","- المواضيع: "+A1+"\n- خرايط عمليات الخدمة ومعاييرها: [الصق]","الحل لازم يستهدف السبب مش العَرَض","- كل سبب مربوط بخطوة في العملية بدليل\n- الافتراضات متعلمة [للتحقق]","جدول الأسباب لكل موضوع."]],
['Write the improvement memo','اكتب مذكرة التحسين',["Office manager to the director of citizen services","Turn the cause analysis into an improvement memo for leadership","- Causes: "+O2,"The director must approve owners and dates","- Max 4 actions with owner, cost estimate as [TO ESTIMATE] if unknown, and date\n- Decision requested clearly","One-page formal Arabic memo."],["مدير مكتب مدير خدمة المواطنين","حوّل تحليل الأسباب لمذكرة تحسين للقيادة","- الأسباب: "+A2,"المدير لازم يعتمد المسؤولين والمواعيد","- أقصى 4 إجراءات بالمسؤول والتكلفة [للتقدير] لو مش معروفة والميعاد\n- القرار المطلوب واضح","مذكرة رسمية بالعربي في صفحة."]]]);
CH('health','From rejected claims to a revenue cycle fix','من المطالبات المرفوضة لإصلاح دورة الإيراد',[
['Classify rejections','صنّف الرفض',["Insurance claims analyst in a hospital","Classify last month’s rejected claims by reason, insurer and department","- Attached: claims export (claim no., insurer, department, service code, amount, rejection reason) — no patient names","Finance needs to know where money is stuck","- Counts and amounts from the file only\n- Unclear reasons kept as Unclassified","Rejection table by reason, insurer and department."],["محلل مطالبات تأمين في مستشفى","صنّف المطالبات المرفوضة الشهر اللي فات حسب السبب وشركة التأمين والقسم","- مرفق: تصدير المطالبات (رقم المطالبة، شركة التأمين، القسم، كود الخدمة، المبلغ، سبب الرفض) — من غير أسامي مرضى","المالية محتاجة تعرف الفلوس واقفة فين","- العدد والمبالغ من الملف بس\n- الأسباب المش واضحة تفضل «غير مصنفة»","جدول الرفض حسب السبب وشركة التأمين والقسم."]],
['Trace the process gaps','تتبّع فجوات العملية',["Revenue cycle process lead","Trace the top rejection reasons to steps in registration, pre-approval, coding or billing","- Classification: "+O1+"\n- Our claims workflow: [paste]","Fixing the step stops repeat rejections","- Each reason linked to one workflow step\n- Clinical documentation issues routed to doctors, not rewritten","Gap table with workflow step and owner."],["قائد عمليات دورة الإيراد","تتبّع أهم أسباب الرفض لخطوات التسجيل أو الموافقة المسبقة أو الترميز أو الفوترة","- التصنيف: "+A1+"\n- مسار المطالبات عندنا: [الصق]","إصلاح الخطوة بيوقف تكرار الرفض","- كل سبب مربوط بخطوة واحدة\n- مشاكل التوثيق الطبي تروح للدكاترة ومتتكتبش من جديد","جدول الفجوات بالخطوة والمسؤول."]],
['Write the action plan','اكتب خطة العمل',["Hospital finance manager’s assistant","Turn the gap table into a 30-day action plan for the revenue cycle committee","- Gaps: "+O2,"The committee must approve owners and dates","- Max 5 actions with owner and date\n- Expected effect stated as a range from the file, not invented","One-page action plan."],["مساعد مدير مالية المستشفى","حوّل جدول الفجوات لخطة عمل 30 يوم للجنة دورة الإيراد","- الفجوات: "+A2,"اللجنة لازم تعتمد المسؤولين والمواعيد","- أقصى 5 إجراءات بالمسؤول والميعاد\n- الأثر المتوقع كمدى من الملف مش متألف","خطة عمل في صفحة."]]]);

// ===== Part D day in the life =====
DL('gov',[['08:30','Triage citizen requests','فرز طلبات المواطنين','Chat + file','From today’s masked requests export, group by service and flag anything past the service standard.','من تصدير طلبات النهارده بعد إخفاء البيانات، جمّع حسب الخدمة وعلّم أي حاجة عدّت معيار الخدمة.',30],['10:00','Draft official letters','كتابة الخطابات الرسمية','Project','Using our approved letter style, draft the reply to incoming no. [x] from the director’s notes; mark anything unconfirmed.','بأسلوب الخطابات المعتمد عندنا، اكتب الرد على الوارد رقم [x] من ملاحظات المدير؛ وعلّم أي حاجة مش متأكدة.',40],['11:30','Check a tender file','مراجعة ملف مناقصة','Chat + file','List every mandatory document and condition in this tender booklet as a checklist with page numbers.','طلّع كل مستند وشرط إلزامي في كراسة الشروط دي كقائمة بأرقام الصفحات.',45],['13:00','Prepare a meeting brief','تحضير ملخص اجتماع','Chat','Summarise these 3 reports into a one-page brief with decisions needed and open questions.','لخّص التقارير الـ 3 دي في صفحة فيها القرارات المطلوبة والأسئلة المفتوحة.',25],['15:00','Update initiative tracker','تحديث متابعة المبادرات','Claude in Excel','From project.csv, show delayed milestones with owner and days late.','من project.csv، اعرض المراحل المتأخرة بالمسؤول وعدد أيام التأخير.',20],['16:30','Write meeting minutes','كتابة محضر الاجتماع','Chat','Turn my notes into formal minutes: attendees, decisions, actions with owners and dates.','حوّل ملاحظاتي لمحضر رسمي: الحضور، القرارات، الإجراءات بالمسؤول والميعاد.',20]]);
DL('health',[['08:00','Check today’s clinic schedule','مراجعة جدول عيادات النهارده','Chat + file','From the masked schedule export, list empty and overbooked slots per clinic.','من تصدير الجدول بعد إخفاء البيانات، طلّع المواعيد الفاضية والزيادة لكل عيادة.',25],['09:30','Chase pre-approvals','متابعة الموافقات المسبقة','Chat + file','List pending pre-approvals older than [x] days by insurer with the missing document for each.','طلّع الموافقات المسبقة المعلقة من أكتر من [x] يوم حسب شركة التأمين والمستند الناقص لكل واحدة.',30],['11:00','Answer patient complaints','الرد على شكاوى المرضى','Project','Draft a polite reply to this anonymised complaint using our patient relations policy; no medical opinions.','اكتب رد محترم على الشكوى دي بعد إخفاء الهوية بسياسة علاقات المرضى عندنا؛ من غير آراء طبية.',25],['13:00','Review rejected claims','مراجعة المطالبات المرفوضة','Claude in Excel','Group this week’s rejected claims by reason and insurer with totals.','جمّع المطالبات المرفوضة الأسبوع ده حسب السبب وشركة التأمين بالإجماليات.',35],['15:00','Prepare the quality meeting','التحضير لاجتماع الجودة','Chat','Summarise this month’s service indicators vs target and 3 issues to discuss.','لخّص مؤشرات الخدمة الشهر ده مقابل المستهدف و3 مواضيع للنقاش.',30],['16:30','Plan tomorrow’s staffing','تخطيط موظفين بكرة','Chat','Compare tomorrow’s bookings with the front-desk roster and flag peak hours short of staff.','قارن حجوزات بكرة بجدول موظفين الاستقبال وعلّم ساعات الذروة اللي فيها نقص.',15]]);

